from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
T0=datetime(2026,10,1,tzinfo=timezone.utc)
def p(status="captured", amt="80.00", ref="0.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0,refunded_amount=Decimal(ref))
# full refund sets status
x=p(); outage_refund(x,Decimal("80.00"),T0); print(x.refunded_amount,x.status)
# partial then full
x=p(); outage_refund(x,Decimal("30.00"),T0); print(x.refunded_amount,x.status); outage_refund(x,Decimal("50.00"),T0); print(x.refunded_amount,x.status)
# errors
for args in [("0.00",),("-1.00",),("81.00",)]:
    try: outage_refund(p(),Decimal(args[0]),T0)
    except BillingError as e: print("err",e.code)
try: outage_refund(p(status="authorized"),Decimal("1.00"),T0)
except BillingError as e: print("err",e.code)
try: outage_refund(p(),Decimal("1000.01"),T0)
except BillingError as e: print("err",e.code)
x=p(); outage_refund(x,Decimal("1000.01"),T0,approved_by="mgr"); print("approved",x.refunded_amount)
EOF"}

